struct OpusHead{
  int           version;
  int           channel_count;
  unsigned      pre_skip;
  opus_uint32   input_sample_rate;
  int           output_gain;
  int           mapping_family;
  int           stream_count;
  int           coupled_count;
  unsigned char mapping[OPUS_CHANNEL_COUNT_MAX];
};

struct OpusTags{
  char **user_comments;
  int   *comment_lengths;
  int    comments;
  char  *vendor;
};

struct OpusPictureTag{
  opus_int32     type;
  char          *mime_type;
  char          *description;
  opus_uint32    width;
  opus_uint32    height;
  opus_uint32    depth;
  opus_uint32    colors;
  opus_uint32    data_length;
  unsigned char *data;
  int            format;
};

struct OpusServerInfo{
  char        *name;
  char        *description;
  char        *genre;
  char        *url;
  char        *server;
  char        *content_type;
  opus_int32   bitrate_kbps;
  int          is_public;
  int          is_ssl;
};

struct OpusFileCallbacks{
  op_read_func  read;
  op_seek_func  seek;
  op_tell_func  tell;
  op_close_func close;
};

